(window.FREALLY_I18N = window.FREALLY_I18N || {})["hi"] = {"hero.headline":"<span class=\"hl-muted\">इसे शीशे पर रखें। START दबाएँ।</span> <span class=\"cycle\" data-cycle=\"hero.cycle\">कॉपी को खींचें।</span>","hero.cycle":"कॉपी को खींचें।|MIDI को खींचें।|ऑडियो को खींचें।","hero.sub":"ऑडियो अंदर, MIDI बाहर। MIDI अंदर, ऑडियो बाहर। मुफ़्त, ऑफ़लाइन और 100% AI-मुक्त।","hero.chipStandalone":"स्टैंडअलोन","what.title":"यह क्या है","what.p1":"किसी लूप को MIDI में, या किसी MIDI फ़ाइल को ऑडियो में बदलने के लिए आमतौर पर औज़ारों की एक श्रृंखला, एक एक्सपोर्ट, एक दोबारा इम्पोर्ट, और यह अनुमान लगाने में बहुत मेहनत लगती है कि नतीजा क्या निकला।","what.p2":"Flipcopy एक कॉपी मशीन है। इसके शीशे पर कोई ऑडियो फ़ाइल या MIDI फ़ाइल रखें और यह मूल को छापता है — असली वेवफ़ॉर्म, या हर नोट, उसके डेटा सहित। हरा START दबाएँ और यह कॉपी को दूसरे रूप में छापता है: ऑडियो अंदर, MIDI बाहर; MIDI अंदर, ऑडियो बाहर।","what.p3":"कॉपी एक छपे पन्ने के रूप में बाहर आती है, जिसके क्लिप के चारों ओर चमकीला हरा फ़्रेम होता है। फ़्रेम पकड़ें और इसे अपने DAW के किसी ट्रैक पर खींच लाएँ। हर कॉपी एक असली फ़ाइल है जो अपनी जगह पर टिकी रहती है, इसलिए आपका प्रोजेक्ट इसे कभी नहीं खोता।","see.title":"इसे कॉपी करते देखें","see.intro":"कॉपियर, Blender में रेंडर किया गया: मूल शीशे पर आकर टिकता है, ढक्कन बंद होता है, लैंप सरकता है, और कॉपी ट्रे पर फिसलकर बाहर आ जाती है।","see.start":"इसे कॉपी करते देखने के लिए START दबाएँ","see.audioToMidi":"ऑडियो अंदर, MIDI बाहर: हर परत का अपना पन्ना — धुन, कॉर्ड्स, बासलाइन और काउंटरमेलोडी।","see.midiToAudio":"MIDI अंदर, ऑडियो बाहर।","features.title":"इसमें क्या है","features.copier.title":"कॉपियर","features.copier.body":"Blender में रेंडर किया गया एक फ़ोटो-वास्तविक कॉपी मशीन। शीशे पर एक क्लिप रखें और यह असली चीज़ छापता है: हर नोट, या असली वेवफ़ॉर्म, उसके टेम्पो, लंबाई और स्तरों सहित।","features.start.title":"हरा START","features.start.body":"क्लिप छोड़ने से वह केवल शीशे पर रखा जाता है। जब तक आप START न दबाएँ, कुछ भी कॉपी नहीं होता, इसलिए वही होता है जो आपने माँगा है।","features.audioToMidi.title":"ऑडियो → MIDI","features.audioToMidi.body":"किसी लूप में मिले ड्रम्स, बास, धुन, काउंटरमेलोडी और कॉर्ड्स — हर एक का अपना पन्ना, एक ही स्कैन से एक के बाद एक छपे, ताकि आप उन्हें अपने DAW में अलग-अलग ट्रैक के रूप में खींच सकें।","features.midiToAudio.title":"MIDI → ऑडियो","features.midiToAudio.body":"एक असली वाद्य यंत्र से बजाई गई MIDI फ़ाइल, और ड्रम मशीन से बजे ड्रम्स, एक ऐसी ऑडियो फ़ाइल के रूप में छपते हैं जिसे आप खींच सकते हैं।","features.drag.title":"कॉपी खींचें","features.drag.body":"हर पन्ने के क्लिप के चारों ओर एक चमकीला हरा फ़्रेम होता है। इसे पकड़ें और किसी ट्रैक पर छोड़ दें। फ़ाइल असली है, और Flipcopy इसे कभी न बदलता है, न मिटाता है।","features.browser.title":"ब्राउज़र","features.browser.body":"Freally Oscillate से लिया गया एक फ़ाइल ब्राउज़र, जिसमें प्रीव्यू प्लेयर है। यह ऑडियो के लिए वेवफ़ॉर्म और MIDI के लिए नोट्स दिखाता है, और MIDI को उसी वाद्य यंत्र से बजाता है जिसे कॉपी उपयोग करती है।","features.daw.title":"किसी भी DAW में","features.daw.body":"CLAP, VST3 और AU, साथ ही बिना DAW के काम करने और Pro Tools के लिए एक स्टैंडअलोन ऐप। Windows, macOS और Linux।","features.free.title":"मुफ़्त, ऑफ़लाइन, बिना AI","features.free.body":"कोई स्तर नहीं, कोई खाता नहीं, कोई टेलीमेट्री नहीं, कोई नेटवर्क नहीं, कोई मॉडल नहीं। पारंपरिक सिग्नल प्रोसेसिंग, जिसे केवल वादा नहीं बल्कि एक बिल्ड गेट लागू करवाता है।","docs.language.title":"भाषाएँ","docs.language.p1":"Flipcopy अठारह भाषाएँ बोलता है। यह आपके सिस्टम की भाषा में शुरू होता है; दूसरी भाषा चुनने के लिए, ब्राउज़र के ऊपर गियर आइकन से सेटिंग्स खोलें और एक चुनें। यह चुनाव कंप्यूटर पर Flipcopy की हर कॉपी पर लागू होता है।","ladder.title":"1.0 की ओर रास्ता","ladder.intro":"हर संस्करण के लिए एक पंक्ति। यह वही सीढ़ी है जिसका निजी योजना भी पालन करती है — अगर एक हिलती है, तो दूसरी भी हिलती है, और एक बिल्ड गेट दोनों की तुलना करता है।","ladder.rung.v0.1.0":"नींव: प्लगइन CLAP, VST3 और AU के रूप में और स्टैंडअलोन ऐप के रूप में लोड होता है, आपके ऑडियो को बिना छेड़े गुज़ार देता है, अपने लाइसेंस की स्वीकृति माँगता है, और हर क्वालिटी गेट चलता है।","ladder.rung.v0.2.0":"कॉपियर और पहली कॉपी: विंडो में मशीन, हरा START, और ऑडियो में कॉपी हुई एक MIDI फ़ाइल जिसे आप सीधे अपने DAW में खींच लेते हैं।","ladder.rung.v0.3.0":"ऑडियो से MIDI: शीशे पर एक लूप रखें, START दबाएँ, और उसके ड्रम्स, बास, धुन और कॉर्ड्स को MIDI के रूप में खींच निकालें।","ladder.rung.v0.4.0":"फ़ाइल ब्राउज़र और प्रीव्यू प्लेयर: कोई सैंपल या MIDI क्लिप खोजें, उसे सुनें, देखें और शीशे पर खींच लाएँ। ज़रूरी सब कुछ यहाँ है।","ladder.rung.v0.5.0":"टच स्क्रीन: कॉपी सेटिंग्स, आपकी कॉपियों के लिए वाद्य यंत्र, फ़ाइल फ़ॉर्मैट, और आपकी बनाई हर कॉपी का इतिहास।","ladder.rung.v0.5.5":"स्टूडियो: किसी भी कॉपी को पियानो रोल में खोलें, उसके नोट्स बदलें, उसे किसी भी वाद्य यंत्र से सुनें, और अपने बदलाव को नई कॉपी के रूप में प्रिंट करें।","ladder.rung.v0.5.7":"मिक्सर और आपके अपने वाद्य यंत्र: हर पार्ट को आकार देने के लिए असली जैसे नॉब, आपके अपने ड्रम किट और सैंपल, पसंदीदा, और एक ही वाद्य-यंत्र लाइब्रेरी जिसे हर Freally ऐप साझा करता है।","ladder.rung.v0.5.9":"स्किन और लाइट मोड: पाँच स्किन, हर एक Blender में रेंडर किया गया उभरा हुआ चेसिस और हर Freally ऐप में एक जैसा, लाइट और डार्क दोनों में, साथ में एक नया लाइट मोड।","ladder.rung.v0.6.0":"हर DAW में: आपके प्रोजेक्ट के साथ सहेजा जाना, एक साथ कई कॉपियाँ, सीधे ट्रैक से स्कैनिंग, और हर DAW में अलग-अलग जाँच।","ladder.rung.v0.7.0":"पूरी ताक़त वाला स्टैंडअलोन ऐप, macOS और Linux, और काम करते हुए कॉपियर का वीडियो।","ladder.rung.v0.8.0":"सटीकता, यथार्थ और गति: बेहतर ट्रांसक्रिप्शन, ज़्यादा विश्वसनीय मशीन, और हर परफ़ॉर्मेंस बजट का सख़्ती से पालन।","ladder.rung.v1.0.0-beta":"मज़बूती: तीन सिस्टम के लिए इंस्टॉलर, वैकल्पिक अपडेट-चेक, और पूरा सचित्र मैनुअल। इस साइट पर अब भी कोई डाउनलोड नहीं।","ladder.rung.v1.0.0-rc":"रिलीज़ कैंडिडेट: हर फ़ाइल की समीक्षा और हर होस्ट की हाथ से जाँच।","ladder.rung.v1.0.0":"रिलीज़ — और इस साइट के अब तक के पहले डाउनलोड।","ladder.rung.v1.1.0":"डॉक्यूमेंट फ़ीडर: पूरा फ़ोल्डर एक ही बार में कॉपी करें।","ladder.rung.v1.3.0":"स्कोर कॉपियाँ: MusicXML और स्टाफ़ नोटेशन में प्रिंट।","ladder.rung.v1.4.0":"दूसरे Freally उत्पादों तक पुल।","ladder.rung.v1.5.0":"प्लगइन (AAX) के रूप में Pro Tools, अगर Avid की शर्तें किसी मुफ़्त उत्पाद के लिए इसकी अनुमति दें।","ladder.rung.v1.6.0":"ग्रूव कॉपियाँ, और मोटे तौर पर बनी, AI-मुक्त स्टेम कॉपियाँ।","ladder.note":"जो संस्करण पूरा हो चुका है वह बना और टैग किया गया है। यह डाउनलोड नहीं है: अभी कोई नहीं है, और 1.0.0 तक कोई नहीं होगा।","honest.title":"वे बातें जिन्हें ज़्यादातर साइटें सबसे नीचे रखती हैं","honest.transcription.title":"मिक्स की MIDI कॉपी एक ट्रांसक्रिप्शन है","honest.transcription.body":"किसी तैयार मिक्स में नोट्स ढूँढना मुश्किल है, और Flipcopy इसे किसी मॉडल की बजाय पारंपरिक सिग्नल प्रोसेसिंग से करता है। यह कुछ नोट्स चूक जाएगा और कुछ ऐसे सुनेगा जो वहाँ हैं ही नहीं। यह जो पाता है वही छापता है, और जो नहीं कर पाया वह बता देता है।","honest.chords.title":"कॉर्ड्स एक प्रोग्रेशन के रूप में वापस आते हैं","honest.chords.body":"कॉर्ड वाला हिस्सा उस प्रोग्रेशन के रूप में छापा जाता है जिसका वह अनुसरण करता है, न कि बजाई गई ठीक-ठीक वॉइसिंग के रूप में, और पन्ना यह साफ़ शब्दों में बताता है।","honest.downloads.title":"1.0.0 से पहले कोई डाउनलोड नहीं है","honest.downloads.body":"इस पन्ने पर कोई बीटा नहीं, कोई प्रीव्यू बिल्ड नहीं, कोई शुरुआती पहुँच नहीं। आधा-अधूरा काम करने वाला कॉपियर उस कॉपियर से बुरा है जो अभी बना ही नहीं।","honest.network.title":"यह कभी ऑनलाइन नहीं जाता","honest.network.body":"प्लगइन और स्टैंडअलोन ऐप में बिल्कुल भी नेटवर्किंग कोड नहीं है, और अगर कभी जोड़ा भी जाए तो एक बिल्ड गेट फेल हो जाता है। किसी आगामी संस्करण में एक अपडेट-चेक जोड़ा जा सकता है, जो तब तक बंद रहेगा जब तक आप उसे चालू न करें, और जिसे एक अलग प्रोग्राम चलाएगा।","site.tagline":"इसे शीशे पर रखें। START दबाएँ। कॉपी को खींचें।","footer.licence":"स्वामित्व वाला — सर्वाधिकार सुरक्षित। © Mike Weaver. आज उपयोग के लिए मुफ़्त; भविष्य के संस्करण बेचे जा सकते हैं। ओपन सोर्स नहीं।","footer.yours":"आपकी बनाई कॉपियाँ आपकी हैं, उतनी ही जितनी कॉपी की गई फ़ाइलें उपयोग के लिए आपकी थीं। Flipcopy के लेखक उन पर कोई स्वामित्व का दावा नहीं करते।","featuresPage.lead":"आपके क्लिप्स के लिए एक कॉपी मशीन। ऑडियो अंदर, MIDI बाहर, उसके हिस्सों में बँटा हुआ; MIDI अंदर, ऑडियो बाहर, असली वाद्य यंत्रों से — और हर कॉपी सीधे आपके DAW में खिंच जाती है।","featuresPage.version":"यह पन्ना Freally Flipcopy संस्करण 1.0 के बारे में है: इस पर लिखा सब कुछ 1.0 में है, और 1.0 के बाद के लिए नियोजित कुछ भी इस पर नहीं है।","featuresPage.numbers.directions":"दिशाएँ: ऑडियो → MIDI और MIDI → ऑडियो","featuresPage.numbers.parts":"तरह के हिस्से जिन्हें यह कॉपी करता है: ड्रम्स, बास, धुन, काउंटरमेलोडी, कॉर्ड्स और एक वोकल लाइन","featuresPage.numbers.instruments":"वाद्य यंत्र, जिनसे MIDI कॉपी बजाई जा सकती है","featuresPage.numbers.bars":"बार: शीशे पर रखा जा सकने वाला सबसे लंबा लूप","featuresPage.numbers.formats":"फ़ाइल फ़ॉर्मैट जिनमें यह लिखता है: MIDI, WAV, AIFF, FLAC और MP3","featuresPage.numbers.plugins":"प्लगइन फ़ॉर्मैट, साथ में एक स्टैंडअलोन ऐप","featuresPage.numbers.systems":"ऑपरेटिंग सिस्टम: Windows, macOS और Linux","featuresPage.numbers.languages":"भाषाएँ","featuresPage.numbers.ai":"AI मॉडल","featuresPage.numbers.price":"आज की क़ीमत","featuresPage.free.title":"आज मुफ़्त","featuresPage.free.body":"Flipcopy आज जो कुछ भी करता है, वह सबके लिए मुफ़्त है: कोई पेड टियर नहीं, कोई सब्सक्रिप्शन नहीं, कोई खाता नहीं और कोई ट्रायल नहीं जो ख़त्म हो जाए। आपकी बनाई कॉपियाँ आपकी हैं, उतनी ही जितनी कॉपी की गई फ़ाइलें उपयोग के लिए आपकी थीं।","featuresPage.cards.title":"संस्करण 1.0 क्या करता है","featuresPage.cards.copier.title":"कॉपियर","featuresPage.cards.copier.body":"Blender में रेंडर की गई एक फ़ोटो-वास्तविक कॉपी मशीन, अपनी आवाज़ों के साथ। शीशे पर एक क्लिप रखें और यह असली चीज़ छापता है — वेवफ़ॉर्म, या हर नोट — उसके डेटा सहित: टेम्पो, लंबाई, नोट्स या स्तर।","featuresPage.cards.start.title":"सिर्फ़ हरा START कॉपी करता है","featuresPage.cards.start.body":"क्लिप छोड़ने से वह केवल शीशे पर रखा जाता है। जब तक आप START न दबाएँ, कुछ भी कॉपी नहीं होता; STOP स्कैन रद्द करता है और HOME शीशा खाली करता है, इसलिए वही होता है जो आपने माँगा है।","featuresPage.cards.audioToMidi.title":"ऑडियो → MIDI, हिस्सों में","featuresPage.cards.audioToMidi.body":"एक लूप अपने भीतर के हिस्सों के रूप में बाहर आता है — ड्रम्स अपनी-अपनी लेन पर, बास, धुन, जहाँ हो वहाँ काउंटरमेलोडी, और कॉर्ड प्रोग्रेशन — हर एक का एक पन्ना और एक MIDI फ़ाइल, एक ही स्कैन से। जो हिस्सा मौजूद नहीं है, उसे कोई पन्ना नहीं मिलता। या किसी वोकल लाइन को अकेले कॉपी करें।","featuresPage.cards.midiToAudio.title":"MIDI → ऑडियो, असली वाद्य यंत्रों से","featuresPage.cards.midiToAudio.body":"एक MIDI फ़ाइल, जिसे Freally MIDI Master के 1,648 वाद्य यंत्रों में से किसी से भी बजाया जाता है — हर हिस्से के लिए एक साउंड और ड्रम्स के लिए एक ड्रम मशीन — और हर हिस्से के लिए एक ऑडियो पन्ने के रूप में छापा जाता है, साथ में पूरा मिक्स। WAV, AIFF, FLAC या MP3, आपकी चुनी सैंपल रेट और बिट डेप्थ पर।","featuresPage.cards.drag.title":"कॉपी खींचें","featuresPage.cards.drag.body":"हर पन्ने पर एक चमकीला हरा फ़्रेम होता है: उसे पकड़ें और फ़ाइल को किसी ट्रैक पर छोड़ दें। या पूरा ढेर खींचें — “सभी हिस्से” हर हिस्से के लिए एक ट्रैक बनकर आता है, “पूरा मिक्स” एक ही क्लिप बनकर। हर फ़ाइल का नाम वैसा ही होता है जैसा आपके DAW को दिखाना चाहिए, जैसे Loop - Bassline - 120 BPM - C# Minor।","featuresPage.cards.copies.title":"कॉपियाँ हमेशा के लिए हैं","featuresPage.cards.copies.body":"हर कॉपी आपके Copies फ़ोल्डर में एक असली, सत्यापित फ़ाइल है — क्रमांकित, और कभी हटाई, बदली या मिटाई नहीं जाती, इसलिए जो प्रोजेक्ट इसका उपयोग करता है वह इसे कभी नहीं खोता। अपनी बनाई हर कॉपी को पलटकर देखें, किसी को फिर से सहेजें, उसे उसके फ़ोल्डर में दिखाएँ, या उसे वापस शीशे पर रखें।","featuresPage.cards.browser.title":"ब्राउज़र और प्रीव्यू प्लेयर","featuresPage.cards.browser.body":"Freally Oscillate से लिया गया एक फ़ाइल ब्राउज़र: 128 फ़ोल्डर तक, पीछे और आगे, टैग, स्टार और कीबोर्ड से नेविगेशन। प्रीव्यू असली वेवफ़ॉर्म या नोट्स दिखाता है, MIDI को उसी साउंड से बजाता है जिसे कॉपी उपयोग करती है, और तैयार ढेर को सिंक में बजाता है, मूल के मुक़ाबले A/B के साथ।","featuresPage.cards.studio.title":"स्टूडियो","featuresPage.cards.studio.body":"किसी भी कॉपी को पियानो रोल में खोलें, हर हिस्से के लिए एक टैब, ठीक Freally MIDI Master की तरह संपादित। उसे किसी भी वाद्य यंत्र से सुनें, असली जैसे नॉब वाले मिक्सर पर उसे आकार दें, उसे अपने ड्रम किट या अपने किसी सैंपल से बजाएँ, और बदलाव को वापस शीशे पर भेजें ताकि वह नई कॉपी के रूप में छपे।","featuresPage.cards.settings.title":"टच स्क्रीन पर सेटिंग्स","featuresPage.cards.settings.body":"कॉपियर की अपनी स्क्रीन पर कॉपी सेटिंग्स होती हैं: कौन-से हिस्से, ग्रिड और स्विंग, टेम्पो और वह कहाँ से आता है, हर हिस्से का साउंड, फ़ाइल फ़ॉर्मैट और टेल। एक बिल्ड गेट जाँचता है कि हर सेटिंग सच में कॉपी को बदलती है।","featuresPage.cards.daw.title":"हर DAW में","featuresPage.cards.daw.body":"Windows, macOS और Linux पर CLAP और VST3, macOS पर AU, और बिना DAW के काम करने के लिए एक स्टैंडअलोन ऐप — और Pro Tools के लिए, खींचकर। आपके प्रोजेक्ट के साथ सहेजा जाता है, एक साथ कई इंस्टेंस में सुरक्षित, और सीधे ट्रैक से स्कैन करने में सक्षम।","featuresPage.cards.skins.title":"स्किन, लाइट और डार्क","featuresPage.cards.skins.body":"पाँच स्किन, हर एक Blender में रेंडर किया गया उभरा हुआ चेसिस जिसे हर Freally ऐप साझा करता है, लाइट और डार्क दोनों में, साथ में सादे लाइट और डार्क मोड। कॉपियर हर एक के लिए दोबारा रेंडर किया जाता है, ताकि वह हमेशा अपनी ही ज़मीन पर खड़ा हो।","featuresPage.cards.offline.title":"ऑफ़लाइन, निजी, बिना AI","featuresPage.cards.offline.body":"कोई टेलीमेट्री नहीं और कोई मॉडल नहीं। हर कॉपी पारंपरिक सिग्नल प्रोसेसिंग से बनती है, और प्लगइन व ऐप कभी ऑनलाइन नहीं जाते। एकमात्र अपवाद एक अपडेट-चेक है, जो तब तक बंद रहता है जब तक आप उसे चालू न करें, और जिसे एक अलग प्रोग्राम चलाता है।","featuresPage.compare.title":"व्यावसायिक औज़ारों के साथ आमने-सामने","featuresPage.compare.intro":"Freally Flipcopy 1.0 उन व्यावसायिक औज़ारों के बगल में, जिनसे प्रोड्यूसर ऑडियो को MIDI में और MIDI को ऑडियो में बदलते हैं। किसी दूसरे उत्पाद का हर सेल उसके निर्माता के अपने पन्नों से लिया गया है, जिन्हें 1 अक्टूबर 2026 को जाँचा गया, और क़ीमतें अक्टूबर 2026 की अमेरिकी सूची क़ीमतें हैं।","featuresPage.compare.feature":"फ़ीचर","featuresPage.compare.row.price":"क़ीमत (USD, अक्टूबर 2026)","featuresPage.compare.freeToday":"आज मुफ़्त","featuresPage.compare.row.audioToMidi":"ऑडियो को MIDI में बदलता है","featuresPage.compare.legend.yes":"उपलब्ध","featuresPage.compare.row.parts":"एक लूप उसके हिस्सों में बँटा, हर हिस्सा अपनी MIDI फ़ाइल में","featuresPage.compare.legend.no":"उपलब्ध नहीं","featuresPage.compare.note.byPitch":"नोट्स अलग करता है, वाद्य यंत्र नहीं","featuresPage.compare.note.byInstrument":"वाद्य यंत्र के अनुसार","featuresPage.compare.legend.partly":"आंशिक","featuresPage.compare.note.byHand":"पहले स्टेम, फिर हर एक हाथ से","featuresPage.compare.row.midiToAudio":"बिल्ट-इन वाद्य यंत्रों से MIDI को ऑडियो में बदलता है","featuresPage.compare.legend.unknown":"सत्यापित नहीं","featuresPage.compare.note.playbackOnly":"बजाता है, पर ऑडियो एक्सपोर्ट नहीं करता","featuresPage.compare.row.drag":"नतीजे को सीधे DAW ट्रैक पर खींचें","featuresPage.compare.note.ara":"कुछ DAW में, ARA के ज़रिए","featuresPage.compare.row.plugin":"प्लगइन के रूप में DAW के अंदर चलता है","featuresPage.compare.note.link":"ऑडियो अपने ही ऐप को भेजता है","featuresPage.compare.note.ownDaw":"सिर्फ़ अपना DAW","featuresPage.compare.note.appOnly":"सिर्फ़ स्टैंडअलोन ऐप","featuresPage.compare.row.systems":"Windows, macOS और Linux","featuresPage.compare.row.noAi":"कोई AI या मशीन लर्निंग नहीं","featuresPage.compare.note.aiStems":"स्टेम अलग करने में इसका उपयोग करता है","featuresPage.compare.summaryTitle":"संक्षेप में","featuresPage.compare.summary":"संक्षेप में: सब कुछ सिर्फ़ Flipcopy में है — दोनों दिशाएँ, हिस्से, खींचना, प्लगइन, तीनों सिस्टम और कोई AI नहीं।","featuresPage.compare.theyWinTitle":"वे कहाँ आगे हैं","featuresPage.compare.theyWin":"जहाँ वे आगे हैं: Melodyne Studio, RipX, AnthemScore और Ableton Live किसी पॉलीफ़ोनिक रिकॉर्डिंग से कॉर्ड के अलग-अलग नोट्स लिख सकते हैं (Melodyne सिर्फ़ अकेले रिकॉर्ड किए गए वाद्य यंत्र से); Flipcopy इसके बजाय आपको प्रोग्रेशन देता है, और यह बताता है। RipX, Ableton Live Suite और Logic Pro किसी मिक्स को ऑडियो स्टेम में अलग भी करते हैं, जो Flipcopy 1.0 नहीं करता।","featuresPage.compare.asOf":"Flipcopy का कॉलम संस्करण 1.0 है, जो अभी जारी नहीं हुआ है, और इसकी क़ीमत आज की है: Flipcopy आज मुफ़्त है, और भविष्य के संस्करण बेचे जा सकते हैं। दूसरे उत्पाद भी बदलते हैं; यह तालिका 1 अक्टूबर 2026 के अनुसार है।","featuresPage.why.title":"यह ऐसे क्यों बना है","featuresPage.why.dsp.title":"पारंपरिक सिग्नल प्रोसेसिंग","featuresPage.why.dsp.body":"ऑनसेट डिटेक्शन, पिच ट्रैकिंग, क्रोमा और एक नियतात्मक रेंडरर, कहीं भी कोई मॉडल नहीं। वही फ़ाइल, वही सेटिंग्स और वही संस्करण हर बार वही कॉपी देते हैं, बाइट-दर-बाइट।","featuresPage.why.print.title":"जो दिखता है, वही खिंचता है","featuresPage.why.print.body":"हर पन्ना उसी फ़ाइल के बाइट्स से बनाया जाता है जिसे वह खींचता है। काग़ज़ पर जो नोट्स, टेम्पो और लंबाई है, वही नोट्स, टेम्पो और लंबाई आपके ट्रैक पर पहुँचती है।","featuresPage.why.honest.title":"ईमानदार कॉपियाँ","featuresPage.why.honest.body":"कोई ख़ाली पन्ना नहीं और ट्रांसक्रिप्शन का रूप धरे कोई अनुमान नहीं। कॉर्ड्स बताते हैं कि वे एक प्रोग्रेशन हैं, शीशे के लिए बहुत लंबी क्लिप काटने के बजाय उसकी लंबाई बताकर लौटा दी जाती है, और जो वोकल लाइन वैसी ही छोड़ दी गई, वह भी यह बताती है।","featuresPage.why.local.title":"यह आपकी मशीन पर ही रहता है","featuresPage.why.local.body":"कोई टेलीमेट्री नहीं और कोई क्लाउड नहीं। आपकी फ़ाइलें और आपकी कॉपियाँ आपके कंप्यूटर से कभी बाहर नहीं जातीं, और अगर कभी प्लगइन या ऐप में नेटवर्किंग कोड जोड़ा जाए तो एक बिल्ड गेट फेल हो जाता है।","featuresPage.why.tempo.title":"यह आपके DAW के साथ चलता है","featuresPage.why.tempo.body":"प्लगइन आपके प्रोजेक्ट का टेम्पो पढ़ता है और उसे कभी नहीं बदलता, और Flipcopy जो भी टेम्पो छापता है, वह बताता है कि वह कहाँ से आया: लूप, फ़ाइल, उसका नाम, आपका DAW, या आप।","featuresPage.why.mix.title":"आपके मिक्स में ग़लती से कुछ नहीं पहुँचता","featuresPage.why.mix.body":"कॉपियर की आवाज़ें और प्रीव्यू प्लगइन से धीमे बजते हैं, और बाउंस में कभी नहीं जाते। जब वे चुप होते हैं, आपके ट्रैक का ऑडियो बिना छेड़े गुज़र जाता है।","featuresPage.coming.title":"अभी क्या आना बाक़ी है","featuresPage.coming.intro":"साफ़-साफ़ कहा गया, क्योंकि जो फ़ीचर सूची अपनी कमियाँ छिपाए, वह पढ़ने लायक नहीं। यह पन्ना संस्करण 1.0 है, और Flipcopy एक-एक पायदान करके बनाया जा रहा है: इस पर लिखा सब कुछ अभी बना नहीं है। 1.0 की ओर रास्ते का हर पायदान अपनी स्थिति के साथ चिह्नित है।","featuresPage.limits.title":"1.0 क्या नहीं करता","featuresPage.limits.chords":"यह मिक्स की गई रिकॉर्डिंग में सुने गए कॉर्ड का हर नोट नहीं लिखता: कॉर्ड्स प्रोग्रेशन के रूप में वापस आते हैं, और पन्ना यह बताता है।","featuresPage.limits.loops":"यह लूप कॉपी करता है, पूरे गाने नहीं: शीशा 16 बार तक की क्लिप लेता है, और लंबी क्लिप को उसकी लंबाई बताकर लौटा देता है।","featuresPage.limits.stems":"यह मिक्स की गई रिकॉर्डिंग को ऑडियो स्टेम में अलग नहीं करता: लूप के हिस्से MIDI के रूप में बाहर आते हैं।","featuresPage.limits.aax":"यह Pro Tools प्लगइन नहीं है: Pro Tools में, स्टैंडअलोन ऐप का उपयोग करें और कॉपी को टाइमलाइन पर खींचें।","featuresPage.coming.downloads":"संस्करण 1.0 से पहले कोई डाउनलोड नहीं है, और इस पन्ने पर भी कोई नहीं।","docs.intro":"यह मैनुअल हर वर्ज़न के साथ बढ़ता है। अभी यह बताता है कि वर्ज़न 0.4.0 क्या करता है; हर कदम के स्क्रीनशॉट वाला पूरा सचित्र मैनुअल बीटा के साथ आएगा।","docs.start.title":"शुरुआत करना","docs.agreement.title":"लाइसेंस अनुबंध","docs.window.title":"विंडो","docs.copier.title":"कॉपी बनाना","docs.browser.title":"ब्राउज़र","docs.preview.title":"प्रीव्यू प्लेयर","docs.report.title":"जब कुछ गड़बड़ हो जाए","docs.privacy.title":"निजता और नेटवर्क","docs.start.p1":"Flipcopy आपके DAW के अंदर CLAP, VST3 या AU प्लगइन के रूप में, या अकेले एक स्टैंडअलोन ऐप के रूप में चलता है। इसे किसी भी ऑडियो ट्रैक पर रखें: यह ट्रैक के ऑडियो को ठीक वैसे ही गुज़ार देता है जैसे वह आता है, इसलिए इसे वहीं छोड़ना सुरक्षित है।","docs.start.p2":"संस्करण 1.0.0 से पहले कोई डाउनलोड नहीं है, और सोर्स कोड निजी है।","docs.agreement.p1":"Flipcopy जब पहली बार खुलता है तो अपना लाइसेंस अनुबंध दिखाता है। इसे अंत तक पढ़ें और सहमत हूँ उपलब्ध हो जाएगा। जब तक आप सहमत नहीं होते, Flipcopy कुछ नहीं पढ़ता, कुछ कॉपी नहीं करता और आपके ट्रैक के ऑडियो में कुछ नहीं जोड़ता।","docs.agreement.p2":"आपका जवाब आपके कंप्यूटर पर रखा जाता है और Flipcopy की हर खुली कॉपी द्वारा साझा किया जाता है, हर DAW में और स्टैंडअलोन ऐप में भी। यदि आप अस्वीकार करते हैं, तो जब भी तैयार हों, दोबारा पढ़ें चुनें।","docs.window.p1":"एक तरफ़ ब्राउज़र है, जिसके नीचे प्रीव्यू प्लेयर लगा है। विंडो का बाकी हिस्सा वह मंच है जहाँ कॉपियर खड़ा है। दोनों के बीच की रेखा को खींचकर ब्राउज़र को चौड़ा या संकरा करें, या उस पर फ़ोकस करके ऐरो कीज़ का उपयोग करें।","docs.window.p2":"ब्राउज़र और उसके प्रीव्यू को समेटने के लिए Ctrl+B (Mac पर Cmd+B) दबाएँ, या ब्राउज़र के किनारे वाला बटन दबाएँ: तब मंच पूरी विंडो ले लेता है। फिर से दबाएँ और वे उसी चौड़ाई पर लौट आते हैं जिस पर आपने उन्हें छोड़ा था। Flipcopy याद रखता है कि आपने क्या चुना।","docs.copier.p1":"कोई ऑडियो या MIDI फ़ाइल ग्लास पर रखें: Explorer या Finder से उसे विंडो में कहीं भी छोड़ें, ब्राउज़र या प्रीव्यू स्ट्रिप से उसे कॉपियर पर खींचें, ब्राउज़र की किसी पंक्ति पर Enter दबाएँ, या खाली ग्लास पर Enter दबाकर एक फ़ाइल चुनें। कॉपियर मूल को छापता है और उसे उल्टा करके ग्लास पर रखता है। ग्लास पर फ़ाइल रखने से कॉपी कभी शुरू नहीं होती।","docs.copier.p2":"हरी START कुंजी दबाएँ, या Ctrl+Enter (Mac पर Cmd+Enter)। ढक्कन बंद होता है, लैंप गुज़रता है, और कॉपी ट्रे में आ जाती है: ऑडियो लूप MIDI बनकर निकलता है, कॉपियर जो भी हिस्सा सुनता है उसके लिए एक पेज; MIDI फ़ाइल ऑडियो बनकर निकलती है, हर हिस्से के लिए एक पेज। Esc या लाल STOP कुंजी इसे रद्द करती है; धूसर HOME कुंजी ग्लास खाली करती है।","docs.copier.p3":"हर पेज Documents/Freally Flipcopy/Copies में एक असली फ़ाइल है, क्रमांकित, और उसे कभी न हटाया जाता है, न ओवरराइट किया जाता है, न मिटाया जाता है। किसी पेज को उसकी छपी क्लिप के चारों ओर के लाइम-हरे फ़्रेम से पकड़ें और सीधे अपने DAW के ट्रैक पर खींचें, या पूरा ढेर एक साथ खींचें।","docs.copier.p4":"कॉपियर की आवाज़ें प्लगइन के अपने आउटपुट से धीमे बजती हैं — DAW चलते समय कभी नहीं और बाउंस में कभी नहीं। सेटिंग्स में इन्हें बंद करें या धीमा करें।","docs.browser.p1":"ब्राउज़र अपनी श्रेणियों पर खुलता है: “कॉपियाँ”, यानी आपके बनाए सभी पेज और मिक्स, और “हाल के”, यानी वे मूल जो आपने हाल में ग्लास पर रखे। इनके नीचे आपके जोड़े हुए फ़ोल्डर होते हैं; एक जोड़ने के लिए “+ फ़ोल्डर जोड़ें” चुनें, 128 तक। जो ड्राइव अभी जुड़ी नहीं है, उस पर रखा फ़ोल्डर अपनी जगह बनाए रखता है और बताता है कि वह अभी कनेक्ट नहीं है। किसी फ़ोल्डर को ब्राउज़ करना बंद करने के लिए उस पर राइट-क्लिक करें, या उसे चुनकर Delete दबाएँ; डिस्क पर कुछ नहीं बदलता।","docs.browser.p2":"किसी फ़ोल्डर को ट्री की तरह देखने के लिए उसे खोलें। नाम से फ़िल्टर करने के लिए टाइप करें, दायरा घटाने के लिए कोई टैग या “तारांकित” चुनें, और Flipcopy जिन सहायक फ़ाइलों को छिपाता है, जैसे .asd और .reapeaks, उन्हें देखने के लिए “सभी फ़ाइलें दिखाएँ” चुनें। “पीछे” और “आगे” आपको उन जगहों से होकर ले जाते हैं जहाँ आप जा चुके हैं।","docs.browser.p3":"↑ और ↓ से पंक्तियों में चलें: जिस पंक्ति पर आप पहुँचते हैं, वह प्रीव्यू में एक बार बजती है। → फ़ोल्डर खोलता है और ← उसे बंद करता है। Enter चुनी हुई फ़ाइल को ग्लास पर रखता है, और उसकी पंक्ति को कॉपियर पर खींचने से भी यही होता है।","docs.browser.p4":"जब आप पहली बार कोई फ़ोल्डर जोड़ते हैं, तो Flipcopy उसकी फ़ाइलें गिनता है, और एक प्रगति पट्टी दिखाती है कि वह कितना आगे पहुँचा है। यह अधिकतम 12 फ़ोल्डर गहराई तक और 50,000 फ़ाइलों तक पढ़ता है, और कभी किसी शॉर्टकट के सहारे फ़ोल्डर से बाहर नहीं जाता।","docs.preview.p1":"प्रीव्यू प्लेयर ब्राउज़र के नीचे रहता है। ऑडियो फ़ाइल अपना असली वेवफ़ॉर्म दिखाती है। MIDI फ़ाइल अपने नोट्स दिखाती है और Preview Piano से बजती है, जो वही साउंड है जिसे कॉपी उपयोग करती है, जब तक आप कोई और न चुनें, ताकि आप सुन सकें कि कॉपी कैसी सुनाई देगी।","docs.preview.p2":"स्पेस बजाता और रोकता है, “बंद करें” शुरुआत पर लौट जाता है, और स्ट्रिप पर क्लिक करने या खींचने से प्लेहेड खिसकता है। “लूप करें” फ़ाइल को दोहराता है, “चुनते ही चलाएँ” (हेडफ़ोन वाला) आपकी चुनी हर फ़ाइल बजाता है, और स्लाइडर स्तर तय करता है। प्रीव्यू Flipcopy के अपने आउटपुट से बजता है और कभी बाउंस में नहीं जाता। किसी भी लंबाई की WAV फ़ाइल बजती है; किसी दूसरे फ़ॉर्मैट की फ़ाइल तब बजती है जब वह पाँच मिनट या उससे छोटी हो।","docs.preview.p3":"सुनने के लिए ग्लास पर रखे मूल पर, या ट्रे के किसी पेज पर क्लिक करें। जब कॉपी पूरी हो जाती है, तो “कॉपी” उसके सभी पेज एक साथ बजाता है और “मूल” ग्लास पर रखी फ़ाइल बजाता है, संगीत में उसी जगह से, ताकि खींचने से पहले आप अंतर सुन सकें। बजाना कभी ज़रूरी नहीं: आख़िरी पेज के टिकते ही पेज खींचे जा सकते हैं।","docs.preview.p4":"स्ट्रिप पर भी पेज जैसा ही लाइम-हरा फ़्रेम होता है। उस फ़ाइल को ग्लास पर रखने के लिए स्ट्रिप को ग्लास पर खींचें।","docs.report.p1":"अगर Flipcopy ख़ुद विफल होता है, जैसे कोई कॉपी जिसे वह लिख नहीं सका, तो स्क्रीन “रिपोर्ट” का विकल्प देती है। यह आपके वेब ब्राउज़र में एक पेज खोलता है जो ठीक-ठीक दिखाता है कि रिपोर्ट में क्या है; जब तक आप वहाँ “भेजें” नहीं दबाते, कुछ नहीं भेजा जाता। जिस फ़ाइल को कॉपियर इसलिए अस्वीकार करता है कि वह बहुत लंबी, ख़ामोश या ऑडियो नहीं है, वह कोई विफलता नहीं है, और स्क्रीन इसके बजाय कारण बताती है।","docs.privacy.p1":"Flipcopy का कोई खाता नहीं है और कोई टेलीमेट्री नहीं है, और प्लगइन तथा स्टैंडअलोन ऐप में बिल्कुल भी नेटवर्किंग कोड नहीं है। आपकी फ़ाइलें और आपकी कॉपियाँ आपके कंप्यूटर से कभी बाहर नहीं जातीं।","docs.privacy.p2":"इसमें किसी भी तरह का AI नहीं है: हर कॉपी पारंपरिक, नियतात्मक सिग्नल प्रोसेसिंग से बनती है, और अगर कभी कोई मशीन-लर्निंग लाइब्रेरी जोड़ी जाए तो एक बिल्ड गेट फेल हो जाता है।","kit.skip":"सामग्री पर जाएँ","kit.nav.site":"साइट","kit.nav.home":"होम","kit.nav.features":"फ़ीचर्स","kit.nav.documentation":"दस्तावेज़ीकरण","kit.nav.changelog":"बदलाव लॉग","kit.nav.language":"भाषा","kit.nav.allApps":"सभी Freally ऐप्स","kit.badge.progress":"v0.4.0 पूरा · आगे v0.5.0","kit.cta.features":"सभी फ़ीचर्स देखें","kit.cta.docs":"दस्तावेज़ीकरण पढ़ें","kit.price":"Freally Flipcopy आज मुफ़्त है, लेकिन हो सकता है कि यह हमेशा मुफ़्त न रहे: भविष्य के संस्करण बेचे जा सकते हैं।","kit.noDownloads":"अभी कोई डाउनलोड नहीं है, और सोर्स कोड निजी है।","kit.label.overview":"अवलोकन","kit.label.inAction":"काम करते हुए","kit.label.inside":"अंदर","kit.label.roadmap":"रोडमैप","kit.ladder.done":"पूरा","kit.ladder.planned":"नियोजित","kit.ladder.goal":"लक्ष्य","kit.ladder.later":"बाद में","kit.label.honesty":"ईमानदारी","kit.family.label":"Freally परिवार","kit.family.title":"<span class=\"hl-muted\">एक परिवार।</span> <span class=\"hl-bright\">आठ ऐप्स।</span>","kit.cta.label":"क्या बदला","kit.cta.title":"<span class=\"hl-muted\">हर संस्करण,</span> <span class=\"hl-bright\">लिखित में।</span>","kit.cta.lede":"बदलाव लॉग में Freally Flipcopy में हुआ हर बदलाव, संस्करण-दर-संस्करण, सभी अठारह भाषाओं में दर्ज है।","kit.cta.changelog":"बदलाव लॉग पढ़ें","kit.footer.thisApp":"यह ऐप","kit.footer.family":"Freally परिवार","kit.status.devVersion":"विकास में · v0.4.0","kit.head.features":"<span class=\"hl-muted\">यह जो कुछ करता है,</span> <span class=\"hl-bright\">आमने-सामने।</span>","kit.label.numbers":"आँकड़ों में","kit.numbers.lead":"हर आँकड़ा ऐप से ही गिना गया है। कुछ भी अनुमानित नहीं है, और कुछ भी बढ़ाकर पूर्णांकित नहीं किया गया है।","kit.label.free":"आज मुफ़्त","kit.label.compare":"तुलना","kit.label.principles":"सिद्धांत","kit.label.limits":"सीमाएँ","kit.states.title":"स्थितियों का अर्थ","kit.states.done":"बना और टैग किया गया, पर इस साइट पर डाउनलोड नहीं","kit.states.planned":"अभी बनना बाकी है","kit.states.goal":"वह संस्करण जिस तक यह रास्ता जाता है","kit.states.later":"उसके बाद, और अभी तय नहीं","kit.states.ladder":"रास्ते का हर पड़ाव देखें","kit.head.documentation":"<span class=\"hl-muted\">यह कैसे काम करता है,</span> <span class=\"hl-bright\">क़दम-दर-क़दम।</span>","kit.search.placeholder":"दस्तावेज़ीकरण में खोजें","kit.docs.contents":"विषय-सूची","kit.head.changelog":"<span class=\"hl-muted\">हर बदलाव,</span> <span class=\"hl-bright\">संस्करण-दर-संस्करण।</span>","kit.changelog.lede":"सबसे नया पहले: Freally Flipcopy में जो कुछ बदला, इस साइट की हर भाषा में।","kit.changelog.versions":"संस्करण","kit.search.none":"इस साइट पर इससे कुछ भी मेल नहीं खाता।","changelog.b0befc5e6040":"<span class=\"release__meta\"><span class=\"release__ver\">v0.4.0</span><time class=\"release__date\" datetime=\"2026-10-05\">2026-10-05</time></span><span class=\"release__title\">फ़ाइल ब्राउज़र और प्रीव्यू प्लेयर</span>","changelog.e884ffe2f90e":"कोई सैंपल या MIDI क्लिप ढूँढ़ें, उसे सुनें, देखें और ग्लास पर रखें — Freally Oscillate का ब्राउज़र और प्रीव्यू प्लेयर, कॉपियर के बगल में। हर ज़रूरी चीज़ यहाँ है: MVP पूरा हो गया है।","changelog.6b02e0d363a4":"जोड़ा गया","changelog.130b73a201db":"<strong>ब्राउज़र।</strong> यह अपनी श्रेणियों पर खुलता है — <strong>कॉपियाँ</strong>, यानी आपके बनाए सभी पेज और मिक्स, और <strong>हाल के</strong>, यानी वे मूल जो आपने हाल में ग्लास पर रखे, हर एक की गिनती के साथ — फिर वे फ़ोल्डर जो आप <strong>+ फ़ोल्डर जोड़ें</strong> से जोड़ते हैं (128 तक)। निकाली गई ड्राइव पर रखा फ़ोल्डर अपनी जगह बनाए रखता है और यह बताता है; किसी फ़ोल्डर को ब्राउज़ करना बंद करने के लिए उस पर राइट-क्लिक करें, या उसे चुनकर <code>Delete</code> दबाएँ, और डिस्क पर कुछ नहीं बदलता। <strong>पीछे</strong> और <strong>आगे</strong> आपको उन जगहों से होकर ले जाते हैं जहाँ आप जा चुके हैं, ठीक Freally Oscillate की तरह।","changelog.3c76294f691c":"<strong>ट्री के रूप में फ़ोल्डर।</strong> इसे खोलें और समेटें, फ़िल्टर करने के लिए टाइप करें, इसे किसी टैग या अपने तारांकित तक सीमित करें, और यह जिन सहायक फ़ाइलों को छिपाता है (<code>.asd</code>, <code>.reapeaks</code> और ऐसी ही) उन्हें देखने के लिए <strong>सभी फ़ाइलें दिखाएँ</strong> चुनें। <code>↑</code>/<code>↓</code> पंक्तियों में चलते हैं और जिस पंक्ति पर आप पहुँचते हैं वह एक बार बजती है; <code>→</code> फ़ोल्डर खोलता है, <code>←</code> उसे बंद करता है, और <code>Enter</code> फ़ाइल को ग्लास पर रखता है।","changelog.9e19fd75f5c5":"<strong>इंडेक्सिंग, जिसे आप देख सकते हैं।</strong> नया फ़ोल्डर अपने अलग थ्रेड पर गिना जाता है, और एक प्रगति पट्टी दिखाती है कि काम कितना आगे पहुँचा — अधिकतम 12 फ़ोल्डर गहराई और 50,000 फ़ाइलें, और कभी किसी शॉर्टकट के सहारे फ़ोल्डर से बाहर नहीं।","changelog.7e5083732503":"<strong>प्रीव्यू प्लेयर</strong>, ब्राउज़र के नीचे लगा हुआ। ऑडियो अपना असली वेवफ़ॉर्म दिखाता है; MIDI फ़ाइल अपने नोट्स दिखाती है और <strong>Preview Piano</strong> से बजती है — ठीक वही साउंड और रेंडर जो कॉपी उपयोग करती है, इसलिए प्रीव्यू ही कॉपी है। <code>Space</code> बजाता और रोकता है; प्लेहेड खिसकाने के लिए स्ट्रिप पर क्लिक करें या खींचें, जो संगीत के आख़िरी नोट तक गिनता है, बार लाइन तक कभी नहीं; साथ में लूप, चुनते ही चलाना और एक स्तर। किसी भी लंबाई की WAV स्ट्रीम होती है; दूसरा फ़ॉर्मैट तब बजता है जब वह पाँच मिनट या उससे छोटा हो। यह प्लगइन के अपने आउटपुट से बजता है और कभी बाउंस में नहीं जाता।","changelog.ca065d9e7b42":"<strong>कॉपी जाने से पहले उसे सुनें।</strong> प्रीव्यू के लिए ग्लास पर रखे मूल या ट्रे के किसी भी पेज पर क्लिक करें; जब कॉपी पूरी हो जाती है, तो <strong>कॉपी</strong> सभी पेज एक साथ बजाता है और <strong>मूल</strong> ग्लास को बजाता है, संगीत में उसी जगह से। यह वैकल्पिक है: आख़िरी पेज टिकते ही पेज खींचे जा सकते हैं, बजाए गए हों या नहीं।","changelog.d17537ff40ec":"<strong>ग्लास पर खींचें।</strong> कोई पंक्ति, या प्रीव्यू स्ट्रिप — जिस पर पेज जैसा ही लाइम फ़्रेम है —, कॉपियर पर खींचने से वह फ़ाइल ग्लास पर रख दी जाती है, और उसका एक छोटा प्रिंट पॉइंटर के साथ चलता है। START से पहले कुछ शुरू नहीं होता।","changelog.cda58c5f73eb":"<strong>ब्राउज़र छिपाएँ</strong> <code>Ctrl+B</code> (Mac पर <code>Cmd+B</code>) से या उसके किनारे वाले बटन से: मंच पूरी विंडो ले लेता है और घूमता शीर्षक फिर से बीच में आ जाता है। Flipcopy इसे याद रखता है।","changelog.5d236e4be21d":"<strong>ऐप से ही समस्या की रिपोर्ट करें।</strong> जब Flipcopy ख़ुद विफल होता है, तो स्क्रीन <strong>रिपोर्ट</strong> का विकल्प देती है, जो आपके वेब ब्राउज़र में रिपोर्ट पेज खोलता है और ठीक-ठीक दिखाता है कि उसमें क्या है; जब तक आप वहाँ “भेजें” नहीं दबाते, कुछ नहीं भेजा जाता।","changelog.2a6141e43be0":"बदला गया","changelog.49de87a64bae":"<strong>डॉक्स साइट</strong> साझा Freally साइट किट से बनी है, जो हर Freally साइट पर एक जैसी है, और इसका मैनुअल इस वर्ज़न के लिए अपडेट किया गया है।","changelog.1246fc93bca0":"ठीक किया गया","changelog.b0f81c543dda":"<strong>पॉइंटर के नीचे का पेज अब हर विंडो आकार पर मिलता है।</strong> विंडो स्केल होते ही किसी पेज पर क्लिक या खींचना गलत जगह पर पड़ता था।","changelog.2096d3c4bbd8":"<span class=\"release__meta\"><span class=\"release__ver\">v0.3.0</span><time class=\"release__date\" datetime=\"2026-10-01\">2026-10-01</time></span><span class=\"release__title\">ऑडियो → MIDI: जादुई पल</span>","changelog.df6f06284fdc":"ग्लास पर कोई ऑडियो लूप रखें, START दबाएँ, और उसका MIDI बाहर आता है — कॉपियर जो भी परत सुनता है उसका एक पेज, एक ही स्कैन से एक के बाद एक, हर एक की अपनी फ़ाइल, लाइम फ़्रेम में, जिसे आप अपने DAW में अकेले या सबको एक साथ खींच सकते हैं। कई हिस्सों वाली MIDI फ़ाइल भी इसी तरह बाहर आती है: हर हिस्से का एक ऑडियो पेज, और पूरी फ़ाइल एक मिक्स के रूप में।","changelog.24a7fe5481b4":"<strong>ऑडियो → MIDI।</strong> किसी ऑडियो लूप को उसकी परतों में पढ़ा जाता है — ड्रम, बास, मेलोडी, जहाँ लूप में दूसरी, स्वतंत्र लाइन हो वहाँ एक <strong>काउंटर-मेलोडी</strong>, और कॉर्ड — MIDI Master के पारंपरिक-DSP एक्सट्रैक्टर से (कोई AI नहीं)। मिली हर परत का अपना पेज और अपनी <code>.mid</code> होती है, जिसका नाम वैसा ही होता है जैसा DAW दिखाता है (<em>Loop - Bassline - 120 BPM - C# Minor</em>); जो परत मौजूद नहीं, उसे कोई पेज नहीं मिलता, और जिस लूप में कोई नोट ही नहीं, उसे ख़ाली कॉपी करने के बजाय अस्वीकार कर दिया जाता है। स्केल तभी छापा जाता है जब वह साफ़ पढ़ा गया हो।","changelog.0c3d252fc872":"<strong>पेजों का ढेर।</strong> एक ही स्कैन से पेज एक के बाद एक बाहर आते हैं, ट्रे पर पंखे की तरह फैले, हर एक पर उसके रूप और हिस्से का शीर्षक (<em>MIDI मेलोडी</em>, <em>ऑडियो बेसलाइन</em>) और <em>पेज n/N</em> होता है। किसी पेज को सबसे ऊपर लाने के लिए उस पर क्लिक करें। <strong>आख़िरी पेज के टिक जाने तक कुछ भी नहीं खिंचता।</strong>","changelog.55fa665ebb50":"<strong>तैयार ढेर से दो ड्रैग।</strong> सबसे ऊपर वाले पेज पर दो लाइम टैब होते हैं: <strong>सभी हिस्से</strong> हर पेज को अलग-अलग फ़ाइलों के रूप में खींचता है, ताकि DAW उन्हें हर परत के लिए एक ट्रैक में सजा दे; <strong>पूरा मिक्स</strong> सब कुछ की एक फ़ाइल खींचता है — हर हिस्से वाली मल्टी-ट्रैक <code>.mid</code>, या पूरा रेंडर <code>.wav</code> के रूप में — जो पेजों के बगल में लिखी जाती है और कभी छापी नहीं जाती। मिक्स के तथ्य देखने के लिए टैब पर होवर करें; पॉइंटर न हो तो <em>पूरा मिक्स इस रूप में सहेजें…</em> उसे सहेजता है।","changelog.7ab067eeb165":"<strong>MIDI → ऑडियो, हिस्सा-दर-हिस्सा।</strong> कई हिस्सों वाली MIDI फ़ाइल हर हिस्से का एक ऑडियो पेज छापती है (<em>ऑडियो मेलोडी</em>, <em>ऑडियो बेसलाइन</em>), हर एक अलग से रेंडर किया गया और अपनी ही WAV से बना, साथ में पूरा मिक्स — हिस्सों का जोड़ ही मिक्स है, एक ही हेडरूम गेन के तहत।","changelog.71cfe75f90c6":"<strong>16 बार तक के लूप।</strong> ग्लास लंबी क्लिप को उसकी लंबाई बार में बताकर अस्वीकार करता है, उसे कभी छोटा नहीं काटता; एक, दो या चार बार का लूप अब भी कॉपी होता है। किसी ऑडियो लूप के बार उसी टेम्पो पर गिने जाते हैं जिस पर कॉपियर उसे पढ़ता है।","changelog.6aed786b024a":"<strong>ईमानदार पेज।</strong> कॉर्ड पेज बताता है कि वह एक प्रोग्रेशन है, बजाई गई वॉइसिंग नहीं; जब कोई गायन पंक्ति सुनी गई और वैसी ही छोड़ दी गई, तो पहला पेज यह बताता है, और जो लूप सिर्फ़ एक गायन पंक्ति है उसे यही कहकर अस्वीकार किया जाता है, “कॉपी करने को कुछ नहीं” कहकर नहीं। छपा हर टेम्पो बताता है कि वह कहाँ से आया — लूप से पढ़ा गया, या जब लूप की हिट्स किसी ग्रिड पर न बैठें, तो होस्ट का, फ़ाइल नाम का या डिफ़ॉल्ट।","changelog.cb05cd0fc0f0":"<strong><code>flipc</code></strong>, कमांड लाइन, जो प्लगइन का अपना ग्लास और कॉपियर चलाती है: <code>flipc copy &lt;file&gt; --out &lt;dir&gt;</code>, <code>flipc facts &lt;file&gt;</code> (डेटा ब्लॉक ठीक वैसा जैसा काग़ज़ छापता है), <code>flipc score</code> (कॉर्पस स्कोरर) और <code>flipc bench</code> (टाइमिंग)।","changelog.d2365b73e8bc":"<strong>कॉर्पस गेट।</strong> audioTest कॉर्पस को हर उस लोकल CI रन में स्कोर किया जाता है जहाँ वह मौजूद हो — और जहाँ न हो वहाँ SKIPPED दिखता है — ऐसी न्यूनतम सीमाओं के मुक़ाबले जो सिर्फ़ ऊपर उठती हैं।","changelog.d2a673b21c8f":"<strong>होस्ट के टेम्पो का ब्लॉक-दर-ब्लॉक पालन होता है</strong>, और जिस MIDI फ़ाइल का अपना कोई टेम्पो नहीं, वह उसी टेम्पो पर कॉपी होती है जो START दबाने के पल होस्ट का होता है।","changelog.ee270218636c":"<strong>सेशन टेम्पो सिर्फ़ ऑक्टेव की बराबरी तोड़ता है।</strong> 90 BPM के सेशन में छोड़ा गया 120 BPM का लूप 120 (चार बार) पर पढ़ा जाता है, 90 (तीन) पर नहीं — MIDI Master के साझा एक्सट्रैक्टर में ठीक किया गया, लूप पढ़ने वाले हर Freally उत्पाद के लिए।","changelog.ab8ac52d964e":"<strong>आज मुफ़्त, हमेशा के लिए वादा नहीं।</strong> Freally Flipcopy आज मुफ़्त है, लेकिन हो सकता है कि यह हमेशा मुफ़्त न रहे: भविष्य के संस्करण बेचे जा सकते हैं। अब डॉक्स साइट का हर पेज यही बताता है।","changelog.7fb464e21cf8":"<strong>रिपॉज़िटरी स्थानांतरित हुई</strong> — अब यह मेंटेनर के अपने GitHub खाते में है, निजी और सर्वाधिकार सुरक्षित; साझा Freally crates बगल के Freally MIDI Master और Freally Oscillate से आते हैं, और प्लगइन का वेब पता अब डॉक्स साइट का नया पता है।","changelog.c584da8d5dfd":"<strong>कंटीन्यूअस इंटीग्रेशन मेंटेनर की मशीन पर चलता है</strong>, हर पुश से पहले — Windows पर हर गेट, और Linux के गेट Docker Desktop में — और GitHub Actions पर कोई नहीं। हर कमिट में <code>[skip ci]</code> होता है। (2026-09-30 को कुछ घंटों के लिए रिपॉज़िटरी सार्वजनिक थी और हर पुश पर CI GitHub पर चला।)","changelog.79a07e8925af":"<strong>एडिटर अपनी ख़ुद की ब्राउज़र प्रोफ़ाइल रखता है।</strong> Flipcopy का WebView2 डेटा (<code>%APPDATA%\\Freally Flipcopy\\webview</code>) Freally MIDI Master के फ़ोल्डर में रखा जा रहा था, और एक ही WebView2 प्रोफ़ाइल साझा करने वाले दो उत्पाद, एक ही DAW में साथ चलने पर, एक-दूसरे का एडिटर ख़ाली छोड़ सकते हैं। अब यह Flipcopy की अपनी है।","changelog.72de476110e3":"<strong>किसी कॉपी का पूरा मिक्स हमेशा उसकी अपनी ही फ़ाइल हो सकता है</strong>: कॉपियर के पीछे से बदली गई <code>record.json</code> किसी ड्रैग, “इस रूप में सहेजें” या “कॉपी को उसके फ़ोल्डर में दिखाएँ” को कहीं और नहीं भेज सकती।","changelog.427549a6dab4":"<strong>कॉपी या तो पूरी लिखी जाती है या बिल्कुल नहीं।</strong> हर पेज और मिक्स, किसी के भी अपना नाम लेने से पहले, डिस्क पर होते हैं, इसलिए बीच में हुई विफलता कभी किसी क्रमांकित फ़ोल्डर में ऐसे पेज नहीं छोड़ती जिनका मालिक कोई कॉपी न हो।","changelog.2604a6288e96":"<strong>कोई पेज क्लिप नहीं होता।</strong> एकमात्र हेडरूम गेन उन सभी फ़ाइलों से तय होता है जो कोई कॉपी लिखती है — कोई हिस्सा मिक्स से ऊपर पीक कर सकता है, जहाँ बाक़ी हिस्से उसे काट देते हैं।","changelog.c6cb2c38dd63":"<strong>एक टिक ज़्यादा लंबा एक्सपोर्ट हुआ 16 बार का लूप 16 बार का ही है</strong>, 17 का नहीं — बार लाइन के 1/32 नोट बाद छोड़ा गया आख़िरी नोट अपने आप में एक बार नहीं है।","changelog.2ba628500475":"<strong>कंट्रोलर पेज तक पहुँचते हैं</strong>, उस चैनल पर भी जो कोई नोट नहीं बजाता।","changelog.833039ba4e85":"<span class=\"release__meta\"><span class=\"release__ver\">v0.2.0</span><time class=\"release__date\" datetime=\"2026-09-30\">2026-09-30</time></span><span class=\"release__title\">कॉपियर और पहली कॉपी</span>","changelog.35409a92a233":"कॉपियर स्टेज पर खड़ा है और Blender में बने कॉपियर की कहानी वाले वीडियो के दृश्य उन्हीं के क्रम में चलाता है: ग्लास पर एक MIDI फ़ाइल छोड़ें, हरा START दबाएँ, और एक असली ऑडियो कॉपी ट्रे पर बाहर आती है — अपनी ही फ़ाइल से छपी, लाइम फ़्रेम में, जिसे आप सीधे अपने DAW में खींच लेते हैं।","changelog.c12f4045ef96":"<strong>स्टेज पर कॉपियर।</strong> मशीन उसी Blender दृश्य से रेंडर की गई है जिससे कहानी वाले दोनों वीडियो बने हैं — उसका आधार, स्प्राइट फ़्रेम के रूप में उसका ढक्कन, दबी हुई कुंजियाँ, ग्लास और ट्रे के मैट — और यह विंडो की अपनी ज़मीन (<code>#090c09</code>) पर पारदर्शी फ़िल्म में रेंडर हुई है, ताकि कमरे में बिना किसी जोड़ के खड़ी रहे। चरण वीडियो के ही दृश्य हैं, वीडियो के ही क्रम में (शीट पलटकर उल्टी टिकती है, ढक्कन उछाल के साथ बंद होता है, START की बीप, लैंप एक ओर से दूसरी ओर घूमता है और सामने की दरार से सियान रोशनी रिसती है जबकि पूरा कमरा मंद पड़ता है, कॉपी ट्रे पर फिसलकर आती है), ऐप के अंदर वाले छोटे कट की कम अवधियों पर; अगर ऐप कभी ऐसा दृश्य चलाए जो कहानी में नहीं है, कोई दृश्य छोड़ दे, या उन्हें क्रम से बाहर चलाए, तो एक टेस्ट फ़ेल हो जाता है। विंडो जितनी जगह देती है, मशीन उसे भर देती है और दाएँ-से-बाएँ भाषा में कभी उल्टी नहीं होती।","changelog.81d392181aa1":"<strong>हरा START ही एकमात्र ट्रिगर है।</strong> क्लिप छोड़ने से वह सिर्फ़ ग्लास पर रखी जाती है। START (या <code>Ctrl/Cmd+Enter</code>, जो वही कुंजी दबाता है) कॉपी शुरू करता है; STOP (या <code>Esc</code>) उसे स्कैन के बीच में रद्द करता है और पीछे कुछ नहीं छोड़ता; HOME ग्लास खाली करता है। कुंजी पर तिरछा <em>START</em> लिखा है, जो टच पैनल की ओर मुड़ा है, और जब भी कॉपी शुरू हो सकती है उसकी LED जलती है। एक प्लगइन टेस्ट हर कमांड भेजता है और फ़ेल हो जाता है अगर <code>copier_start</code> के सिवा कोई भी कमांड काम शुरू करे, और अगर पेज कभी इसे START कुंजी के सिवा कहीं और से भेजे तो एक बिल्ड गेट फ़ेल हो जाता है।","changelog.3c73db8b1385":"<strong>ग्लास।</strong> Explorer या Finder से कोई ऑडियो या MIDI फ़ाइल विंडो में कहीं भी छोड़ें (आते ही ग्लास जगमगा उठता है), या खाली ग्लास पर <code>Enter</code> दबाकर एक चुनें। वह अपने अलग थ्रेड पर पढ़ी जाती है और टिकने से पहले सीधी छापी जाती है — असली नोट या असली वेवफ़ॉर्म, फ़ाइल के अपने तथ्यों के साथ। नेटवर्क पाथ, बहुत बड़ी, बहुत लंबी, ख़ामोश, ख़राब, SMPTE-टाइम वाली और फ़ॉर्मैट-2 MIDI फ़ाइलें — हर एक को उसके अपने वाक्य के साथ अस्वीकार किया जाता है। एक साथ दो फ़ाइलें: पहली रखी जाती है, और मशीन कहती है एक बार में एक क्लिप। तैयार कॉपी पर छोड़ी गई नई क्लिप भी उसी तरह ग्लास पर रखी जाती है, और ट्रे खाली हो जाती है (कॉपी Copies फ़ोल्डर में रहती है)। जिस फ़ाइल को ग्लास अस्वीकार करता है, वह पहले से रखी क्लिप को जहाँ है वहीं रहने देती है।","changelog.4267b3fd96ac":"<strong>MIDI → ऑडियो।</strong> कॉपी फ़ाइल के नोट्स को एक डिफ़ॉल्ट टोनर से रेंडर करती है — सुर वाले हिस्सों के लिए MIDI Master की अपनी प्रीसेट आवाज़ें, और ड्रम के लिए एक ड्रम मशीन, हर GM लेन की एक आवाज़ — पिच बेंड और सस्टेन पेडल का पालन करते हुए (हर चैनल का, सिर्फ़ उसी चैनल के नोट्स पर), 2.5 s की टेल के साथ, फ़ाइल के टेम्पो पर (वरना होस्ट के — स्टैंडअलोन में वह नहीं होता — वरना फ़ाइल नाम वाले पर, वरना 120 पर — और पेज बताता है कौन-सा), −0.3 dBFS से नीचे रखी गई, और होस्ट के सैंपल रेट (स्टैंडअलोन में 44.1 kHz) पर 24-बिट WAV के रूप में लिखी गई, जिसे DAW बीट ग्रिड पर रखता है। एक कॉपी उतनी ही लंबी हो सकती है जितने से एक पेज छापा जा सके — पाँच मिनट, या 48 kHz से ऊपर 2:30 — और इससे लंबी कॉपी रेंडर होने से पहले ही अस्वीकार कर दी जाती है, कभी छोटी नहीं की जाती। ऑडियो → MIDI <code>v0.3.0</code> में आता है; तब तक ऑडियो क्लिप पर START ईमानदारी से यही बताता है।","changelog.d9714ba71fa5":"<strong>Copies फ़ोल्डर</strong> (<code>Documents/Freally Flipcopy/Copies</code>): हर कॉपी के लिए एक क्रमांकित फ़ोल्डर, जो एटॉमिक रूप से लिया जाता है ताकि दो DAW कभी एक ही नंबर साझा न करें; पेजों के नाम वैसे ही जैसे DAW उन्हें दिखाता है (<code>Title - Part - 120 BPM, Key.wav</code>); हर पेज एटॉमिक रूप से लिखा, वापस पढ़ा और सत्यापित किया जाता है — और <strong>कभी दूसरी जगह ले जाया, ओवरराइट या मिटाया नहीं जाता</strong>, क्योंकि आपका DAW उसे उसके पाथ से पहचानता है।","changelog.48b3f94d470b":"<strong>प्रिंट, ख़ुद फ़ाइलों से।</strong> हर पेज — ग्लास पर रखा मूल और ट्रे में पड़ी कॉपी — कहानी वाले वीडियो के प्रिंट की तरह लेज़र-प्रिंट होता है: शीर्षक, स्रोत पंक्ति, बार रूलर, वेलोसिटी लेन के साथ पियानो रोल या अपनी नई <strong>स्पेक्ट्रम पट्टी</strong> के साथ वेवफ़ॉर्म, और डेटा ब्लॉक — सब कुछ प्लगइन डिस्क पर रखे बाइट्स से गणना करता है। विषम ताल का बार अपनी आधी बीट रखता है (7/8 हर बार में साढ़े तीन बीट छापता है)। कॉपी का पेज बताता है कि उसके रेंडर ने क्या छोड़ा — वे कंट्रोलर जो उसने नहीं बजाए, वे ड्रम नोट जिनके लिए किट में कोई आवाज़ नहीं — उन्हें कभी चुपचाप नहीं गिराता। एक टेस्ट ऐप के पेजों और वीडियो के अपने प्रिंट की संरचना पढ़ता है और दोनों को एक-दूसरे से मिलाकर रखता है।","changelog.fa6958b17901":"<strong>कॉपी को अपने DAW में खींचें।</strong> बाहर निकले पेज की क्लिप के चारों ओर एक लाइम फ़्रेम होता है, जिसके नीचे <em>DAW में खींचें</em> लिखा होता है — फ़्रेम ही हैंडल है। उसके अंदर दबाएँ और 4 px खिसकाएँ, और कॉपी की अपनी फ़ाइल (कर्सर पर एक छोटे प्रिंट के साथ) FL Studio, Ableton, Reaper या फ़ाइलें लेने वाले किसी भी DAW में खिंच जाती है। पेज पूरी तरह बाहर आने तक कुछ नहीं खिंचता; जहाँ यहाँ खींचना संभव नहीं, वहाँ फ़्रेम धूसर और डैश वाला हो जाता है और इसके बजाय “इस रूप में सहेजें” देता है। पेज पर <code>Enter</code> दबाने से “इस रूप में सहेजें” खुलता है या फ़ाइल उसके फ़ोल्डर में दिखती है।","changelog.4da7005c5000":"<strong>मशीन की आवाज़ें</strong>, इस कॉपियर के लिए शुरू से संश्लेषित (रखना, ढक्कन, बीप, स्कैन की शुरुआत, हर लैंप-स्वीप पर एक घरघराहट, इजेक्ट) और प्लगइन द्वारा उसके अपने आउटपुट में मिक्स की गईं — कभी HTML <code>&lt;audio&gt;</code> नहीं — Monitor स्तर के ज़रिए −18 dB पर, आपके DAW के चलते समय चुप (स्टैंडअलोन में ऐसा कोई DAW ट्रांसपोर्ट नहीं जिसके लिए चुप रहना पड़े), ऑफ़लाइन बाउंस में ख़ामोश, और कभी आपके ट्रैक के ऑडियो की जगह नहीं। सेटिंग्स में इन्हें चालू/बंद करना, इनका स्तर, और “DAW चलते समय चुप रहें” का विकल्प है।","changelog.f8fc9e0d2e58":"<strong>टच स्क्रीन</strong> दिखाती है कि मशीन क्या कर रही है, उसमें कौन-सी क्लिप है, और हर अस्वीकृति प्रोड्यूसर की भाषा में।","changelog.1a5ee7d7aabc":"इन सबके लिए <strong>गेट</strong>, हर एक को भरोसा करने से पहले फ़ेल होते देखा गया: ग्राउंड-मैच तिकड़ी (रेंडर के रंग टोकन के बराबर; हर चरण में DPR 1 और 2 पर मशीन के अपने अल्फ़ा सिल्हूट के चारों ओर ΔE2000; मशीन और ज़मीन के बीच कुछ भी पेंट नहीं होता), START गेट (स्टैटिक, प्लगइन और Playwright), प्रिंट समानता, ड्रैग फ़्रेम के पिक्सेल, और असली स्टैंडअलोन में नए ऐप-लेग स्पेक।","changelog.66b1e687636a":"<strong>साझा कोड</strong>: <code>freally-extract</code> (डिकोड का दरवाज़ा और ऑडियो विश्लेषण), <code>freally-encode</code> (WAV, रीसैंपलिंग, DAW-ग्रिड चंक) और <code>freally-drag</code> (नेटिव ड्रैग स्रोत) MIDI Master से <code>shared-v5</code> पर लिए जाते हैं, साथ में <code>freally_library::audition::NoteRenderer</code>, <code>read_facts</code> के कंट्रोलर इवेंट, और वेब व्यू एडैप्टर का फ़ाइल-ड्रॉप हुक, विंडो हिलने पर वेब व्यू को फिर से सही जगह रखना और उसका ख़ाली कैप्शन — ये सब वहीं अपस्ट्रीम में जोड़े गए।","changelog.e7908191194e":"<strong>आइकन मालिक का अपना है</strong> — वेवफ़ॉर्म और पियानो रोल के ऊपर लाइम <em>F</em> — एक्ज़िक्यूटेबल, प्लगइन बंडल, Linux और macOS आइकन और डॉक्स साइट पर, प्लेसहोल्डर की जगह।","changelog.719f74499130":"<strong>विंडो।</strong> स्टैंडअलोन के टाइटल बार पर आइकन है, वह गहरा और कमरे के रंग का है, और कुछ नहीं कहता: न स्टैंडअलोन के टाइटल बार में कोई शीर्षक, न किसी ऐसे DAW में प्लगइन विंडो के टाइटल बार में जिसका कैप्शन Flipcopy का नाम लेता है, क्योंकि विंडो के ऊपर घूमता नाम पहले ही यह बता देता है। वह घूमता नाम दोगुने आकार का है, ताकि एक नज़र में पढ़ा जा सके, और विंडो में कॉपियर वाले हिस्से के ऊपर बीच में है; फ़ाइल ब्राउज़र उसके बगल में विंडो के ऊपर से प्रीव्यू डॉक तक जाता है।","changelog.120afa46c010":"ब्रिज 2 MiB तक के अनुरोध लेता है (एक ड्रैग इमेज); <code>host_info</code> बताता है कि यहाँ कोई पेज खींचा जा सकता है या नहीं।","changelog.df29ffbf7480":"लाइसेंस अनुबंध स्वीकार होने से पहले, पेज एक अलग कमांड (<code>locale_get</code>) के ज़रिए सिर्फ़ इंटरफ़ेस की भाषा पढ़ सकता है, और कुछ नहीं; <code>prefs_get</code> तभी जवाब देता है जब अनुबंध स्वीकार हो जाए।","changelog.bf4a28a43b62":"<strong>स्केल्ड डिस्प्ले पर विंडो हिलाना।</strong> Windows को 150 % पर सेट करने पर, स्टैंडअलोन विंडो को उसके टाइटल बार से खींचने पर उसकी सामग्री विंडो से एक-तिहाई पीछे, स्क्रीन के ऊपरी-बाएँ कोने की ओर बनती थी, जिससे दाएँ और निचले किनारे तब तक छिपे रहते थे जब तक विंडो वापस उस कोने में न ले जाई जाए। अब विंडो जहाँ भी ले जाई जाए, सामग्री ठीक उसके नीचे रहती है।","changelog.f246f03536b6":"<strong>आपके डिस्प्ले के अपने स्केल पर स्टैंडअलोन।</strong> स्केल्ड डिस्प्ले (150 %) पर स्टैंडअलोन एक पुराने ढंग के, बिना स्केलिंग वाले प्रोग्राम की तरह चलता था: Windows उसकी विंडो को खींचकर बड़ा करता था जबकि उसके अंदर का पेज असली पिक्सेल पर बनता था — यहाँ बताई गई ड्रैग और ड्रॉप-डाउन की गलत जगहों की जड़ यही थी। अब यह कोई विंडो खोलने से पहले ख़ुद को प्रति-मॉनिटर DPI अवेयर घोषित करता है, जैसा Freally MIDI Master और Freally Unloop के स्टैंडअलोन करते हैं, ताकि पेज डिस्प्ले के स्केल पर साफ़-सुथरा बने और विंडो अपने इच्छित आकार में खुले।","changelog.4d43aa80977a":"<strong>भाषा सूची अपने फ़ील्ड के नीचे खुलती है।</strong> स्केल्ड डिस्प्ले पर सिस्टम की अपनी ड्रॉप-डाउन सूची सेटिंग्स फ़ील्ड के नीचे और दाईं ओर खुलती थी, और फ़ील्ड विंडो के कोने से जितना दूर होता, उतनी ही दूर; अब सूची Flipcopy ख़ुद बनाता है, ठीक फ़ील्ड के नीचे, विंडो की अपनी गहरी शैली में, और हर भाषा उसकी अपनी लिपि में लिखी होती है।","changelog.a348e37f07eb":"<span class=\"release__meta\"><span class=\"release__ver\">v0.1.0</span><time class=\"release__date\" datetime=\"2026-09-26\">2026-09-26</time></span><span class=\"release__title\">नींव और CI की रीढ़</span>","changelog.8847996db9e9":"वह ख़ाली उत्पाद जिस पर आगे का हर पायदान बनता है: यह लोड होता है, ऑडियो को बिना छेड़े गुज़ार देता है, लाइसेंस अनुबंध माँगता है, अपनी गहरी विंडो खोलता है, और हर क्वालिटी गेट चलता है।","changelog.cc29ebe17a90":"<strong>प्लगइन, एक ही बाइनरी से हर फ़ॉर्मैट में।</strong> एक nih-plug CLAP प्लगइन, जिसके VST3 और AUv2 एंट्री पॉइंट <code>clap-wrapper</code> से बनाए जाते हैं (लाइसेंस की दृष्टि से साफ़: कोई GPL VST3 बाइंडिंग नहीं), साथ में <strong>स्टैंडअलोन ऐप्लिकेशन</strong> — अपनी विंडो और ऑडियो डिवाइस वाला एक नेटिव डेस्कटॉप ऐप, कभी वेब ऐप नहीं। स्टीरियो इन और आउट, आगे आने वाले “ट्रैक से स्कैन” के लिए एक नोट इनपुट, शून्य लेटेंसी, और ट्रैक का ऑडियो <strong>बिट-दर-बिट</strong> गुज़रता है (एक नल टेस्ट इसे साबित करता है)। होस्ट का <strong>Bypass</strong> स्विच और उस आवाज़ के लिए <strong>Monitor</strong> स्तर जो Flipcopy ख़ुद जोड़ेगा (मशीन की आवाज़ें और प्रीव्यू, <code>v0.2.0</code> से) — यह ट्रैक को कभी नहीं छूता। एक संस्करण-युक्त सहेजी गई स्थिति जो सीमित है, माइग्रेट होती है, और आधी लोड होने के बजाय पूरी की पूरी अस्वीकार कर दी जाती है, ताकि कोई ख़राब प्रोजेक्ट होस्ट को कभी क्रैश न करे।","changelog.59616adfaedb":"<strong>लाइसेंस अनुबंध</strong> (<code>EULA.md</code>, Freally Oscillate के अनुबंध की तरह संरचित) और उसका गेट: Flipcopy पहली बार खुलने पर आपसे इसे स्वीकार करने को कहता है और जब तक आप ऐसा नहीं करते, निष्क्रिय रहता है — कुछ नहीं पढ़ता, कुछ कॉपी नहीं करता और आपके ट्रैक में कुछ नहीं जोड़ता। अनुबंध प्लगइन में कंपाइल होता है और वहीं से परोसा जाता है, सहमत हूँ तब तक रुका रहता है जब तक पाठ अंत तक पढ़ न लिया जाए, और आपका जवाब हर खुले इंस्टेंस और स्टैंडअलोन द्वारा साझा किया जाता है। जो अस्वीकृति सहेजी न जा सकी, वह यह बता देती है।","changelog.ed5631790156":"<strong>विंडो</strong>, जो 1400 × 875 (Freally Unloop का आकार) पर खुलती है और किसी भी आकार में एक इकाई की तरह स्केल होती है — हर चीज़ अपना अनुपात बनाए रखती है, चारों ओर कोई पट्टी नहीं — एक ऐसे टाइटल बार के नीचे जहाँ <em>Freally Flipcopy</em> और उसका संस्करण 3D में Y अक्ष पर घूमते हैं, ठीक वैसे ही जैसे Freally Oscillate और Freally MIDI Master में (और कम गति वाली सेटिंग में स्थिर रहते हैं): इनलाइन-स्टार्ट वाली तरफ़ ब्राउज़र रेल और प्रीव्यू डॉक के साथ गहरा शेल, एक खींचने योग्य स्प्लिटर (260–420 px, ऐरो कीज़ से भी), और स्टेज — जिसकी अपनी कोई पृष्ठभूमि नहीं, ताकि कॉपियर कमरे में बिना किसी जोड़ के खड़ा रहे। एक ही थीम, गहरी, और ऐसा कुछ नहीं जो दूसरी थीम बना सके।","changelog.ccf91016802f":"विंडो की हर चीज़ के लिए <strong>अठारह भाषाएँ</strong>; चुनाव हर कंप्यूटर के लिए सहेजा जाता है और हर इंस्टेंस द्वारा साझा किया जाता है; अरबी के लिए दाएँ-से-बाएँ लेआउट।","changelog.92d766745704":"<strong>Google के Noto फ़ॉन्ट</strong>, SIL Open Font License 1.1 के तहत बंडल में शामिल, और उनके बगल में उनका लाइसेंस भी।","changelog.b502e66ba7a3":"<strong>डॉक्स साइट</strong>, Freally Oscillate की साइट की तरह बनी और सिर्फ़ डार्क, उन्हीं अठारह भाषाओं में (हर भाषा तभी लोड होती है जब पाठक उसे चुने): संस्करण-सीढ़ी वाला होम पेज (<code>docs/ladder.json</code> से बनी और एक गेट द्वारा निजी योजना से बँधी), “इसे कॉपी करते देखें” में Blender में बनी कॉपियर की दो कहानियाँ, दस्तावेज़ीकरण, यह बदलाव लॉग, और एक डाउनलोड पेज जो साफ़ कहता है कि <code>v1.0.0</code> से पहले डाउनलोड करने को कुछ नहीं है। कहानियाँ अपनी आवाज़ के साथ चलती हैं, सिर्फ़ तब जब आप कॉपियर की हरी कुंजी पर तिरछा START (या प्ले) दबाएँ, और ख़त्म होने या रोके जाने पर अपने पहले फ़्रेम पर ठहर जाती हैं; ऑडियो → MIDI कहानी हर परत का एक पेज छापती है — MIDI मेलोडी, MIDI कॉर्ड, MIDI बेसलाइन और MIDI काउंटर-मेलोडी — एक के बाद एक ट्रे में एक ढेर पर, हर एक लाइम फ़्रेम में और उसके नीचे <em>DAW में खींचें</em>।","changelog.96a59e69b7f8":"<strong>टेक्स्ट अपने कंटेनरों के अंदर रहता है</strong>, सभी 18 भाषाओं में, डिफ़ॉल्ट विंडो पर भी और सबसे छोटी पर भी (हर लेबल पर एक Playwright जाँच)।","changelog.495bcdf8956e":"<strong>गेट</strong>, हर एक को भरोसा करने से पहले फ़ेल होते देखा गया: फ़ॉर्मैटिंग, clippy, हर टेस्ट, टाइप चेक, लिंट, लोकेल गेट (18 कैटलॉग, एक जैसी कुंजियाँ और प्लेसहोल्डर, सचमुच अनुवादित), लॉजिकल-CSS लिंट, डिज़ाइन टोकन और कंट्रास्ट, सिर्फ़-डार्क, डिनायलिस्ट (कोई AI नहीं, कोई नेटवर्क नहीं, कोई टेलीमेट्री नहीं), लाइसेंस ऑडिट, साझा-क्रेट गेट (उपयोग करें, कभी फ़ोर्क नहीं), उत्पाद नाम (कभी किसी कॉपियर निर्माता का ट्रेडमार्क नहीं), बाइंडिंग ड्रिफ़्ट, सीढ़ी, 1.0 से पहले कोई डाउनलोड नहीं, एसेट बजट, स्ट्रिक्टनेस 10 पर <code>clap-validator</code> और <code>pluginval</code>, Windows पर और Linux के लिए Docker में लोकल CI, और दो लेग पर Playwright — ब्राउज़र और असली स्टैंडअलोन विंडो।","changelog.8f6fb4eb7f42":"सुरक्षा","changelog.09dd8d0ea4e1":"एडिटर सिर्फ़ बाइनरी में कंपाइल किया गया पेज लोड करता है, एक सख़्त Content Security Policy के तहत; उसका ब्रिज सिर्फ़ पेज के अपने JSON <code>POST</code> का जवाब देता है, 64 KiB से बड़ी किसी भी चीज़ और <code>..</code> वाले किसी भी पाथ को अस्वीकार करता है, और अनुबंध स्वीकार होने से पहले सिर्फ़ अनुमत कमांडों की सूची का जवाब देता है। रिलीज़ बिल्ड न कोई DevTools खोलते हैं, न कोई रिमोट-डीबगिंग पोर्ट।","changelog.e06fbd4d3359":"प्लगइन या स्टैंडअलोन में कोई नेटवर्क कोड नहीं, जिसकी जाँच कंपाइलर (<code>clippy.toml</code>) और डिपेंडेंसी ग्राफ़ (<code>scripts/check-denylist.mjs</code>) करते हैं।","changelog.70e17daefb45":"Flipcopy आपके ऐप-डेटा फ़ोल्डर में जो फ़ाइलें रखता है (अनुबंध का जवाब और प्राथमिकताएँ), वे आकार की सीमा के साथ पढ़ी और एटॉमिक रूप से लिखी जाती हैं, ताकि ख़राब या हाथ से बदली गई फ़ाइल डिफ़ॉल्ट के रूप में लोड हो और कोई क्रैश कभी आधी फ़ाइल न छोड़े।"};
